import { useEffect, useRef } from 'react';

import { useSubFilters } from 'hooks';

import { mergePerformanceAndBreakdownWaterfallSubFilterData } from '../__mocks__/Waterfall/waterfallOptions';
import {
  getPerformanceAndBreakdownActiveViewBy,
  getPerformanceAndBreakdownDefaultViewBy,
  isPerformanceAndBreakdownViewByDisabled,
} from '../config/performanceAndBreakdownDeepDive';
import {
  PERFORMANCE_AND_BREAKDOWN_MOCK_ONLY,
  PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_STATE_KEY,
} from '../constants';
import type { PerformanceAndBreakdownWaterfallContextKey } from '../types';

export function usePerformanceAndBreakdownViewBySync(
  contextKey: PerformanceAndBreakdownWaterfallContextKey,
) {
  const {
    activeSubFilters,
    subFiltersData,
    setSubFilterValue,
    setSubFiltersData,
  } = useSubFilters();
  const prevContextKeyRef = useRef(contextKey);

  const defaultViewBy = getPerformanceAndBreakdownDefaultViewBy(contextKey);
  const subFilterValue =
    activeSubFilters?.[PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_STATE_KEY];

  const activeViewBy = getPerformanceAndBreakdownActiveViewBy(
    contextKey,
    subFilterValue,
  );

  const isViewByDisabled = isPerformanceAndBreakdownViewByDisabled(contextKey);

  useEffect(() => {
    if (!PERFORMANCE_AND_BREAKDOWN_MOCK_ONLY) {
      return;
    }

    const merged =
      mergePerformanceAndBreakdownWaterfallSubFilterData(subFiltersData);

    if (merged) {
      setSubFiltersData(merged);
    }
  }, [setSubFiltersData, subFiltersData]);

  useEffect(() => {
    if (prevContextKeyRef.current === contextKey) {
      return;
    }

    prevContextKeyRef.current = contextKey;
    setSubFilterValue(
      PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_STATE_KEY,
      getPerformanceAndBreakdownDefaultViewBy(contextKey),
    );
  }, [contextKey, setSubFilterValue]);

  useEffect(() => {
    if (isViewByDisabled) {
      setSubFilterValue(
        PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_STATE_KEY,
        defaultViewBy,
      );
    }
  }, [defaultViewBy, isViewByDisabled, setSubFilterValue]);

  return { activeViewBy, isViewByDisabled };
}
